.eqv SLEEP_TIME 0

.macro sleep (%millis)
    li $v0, 32
    li $a0, %millis
    syscall
.end_macro

.macro rand_int_range (%dest, %from, %to)
    add $a1, $zero, %to
    sub $a1, $a1, %from
    li $v0, 42
    li, $a0, 0
    syscall
    move %dest, $a0
    add %dest, %dest, %from
.end_macro

.macro print_int (%x)
	li $v0, 1
	add $a0, $zero, %x
	syscall
.end_macro

.macro set_mem (%address, %value, %offset)
    push_stack($t0)
    push_stack($t1)
    add $t0, $zero, %value
    add $t1, $zero, %offset
    sw $t0, %address+0($t1)
    pop_stack($t1)
    pop_stack($t0)
.end_macro

.macro push_stack (%reg)
    addi $sp, $sp, -4
    sw %reg, 0($sp)
.end_macro

.macro pop_stack (%reg)
    lw %reg, 0($sp)
    addi $sp, $sp, 4
.end_macro

.macro save_ra
    push_stack ($ra)
.end_macro

.macro load_ra
    pop_stack ($ra)
.end_macro

.macro save_temp
    push_stack($t0)
    push_stack($t1)
    push_stack($t2)
    push_stack($t3)
    push_stack($t4)
    push_stack($t5)
    push_stack($t6)
    push_stack($t7)
    push_stack($t8)
    push_stack($t9)
.end_macro

.macro load_temp
    pop_stack($t9)
    pop_stack($t8)
    pop_stack($t7)
    pop_stack($t6)
    pop_stack($t5)
    pop_stack($t4)
    pop_stack($t3)
    pop_stack($t2)
    pop_stack($t1)
    pop_stack($t0)
.end_macro

.macro draw_sprite(%label, %width, %height, %x, %y)
    save_ra
    la $v0, %label
    add $a0, $zero, %width
    add $a1, $zero, %height
    add $a2, $zero, %x
    add $a3, $zero, %y
    jal DRAWSPRITE
    load_ra
.end_macro

.macro draw_sprite_memory(%label, %width, %height, %x, %y)
    save_ra
    la $t0, %label
    move $v0, $t0
    lw $a0, %width
    lw $a1, %height
    lw $a2, %x
    lw $a3, %y
    jal DRAWSPRITE
    load_ra
.end_macro

.macro for (%regIterator, %from, %to, %command)
	add %regIterator, $zero, %from
	Loop:
    beq %regIterator, %to, ENDFOR
    save_ra
    jal %command
    load_ra
	add %regIterator, %regIterator, 1
	j Loop
    ENDFOR:
.end_macro


