        lw $t1, mainMenuTitleY
        addi $t1, $t1, -1
        sw $t1, mainMenuTitleY

        sleep (30)
        j MAINMENULOOP
    MAINMENULOOPEND:

    draw_sprite (mainMenuBackground, 128, 46, 0, 0)
    draw_sprite (mainMenuForeground, 128, 34, 0, 30)
    draw_sprite (mainMenuTitle, 126, 30, 1, 3)
    draw_sprite (mainMenuPress, 63, 5, 32, 56)
    jal BUFFTOSCREEN

    MAINMENULOOP2:
        jal KEYBOARDINPUT
        sleep (100)
        j MAINMENULOOP2

GAMEOVERSETUP:
    draw_sprite (gameOverBackground, 128, 64, 0, 0)
    draw_sprite (gameOverTitle, 88, 22, 20, 24)
    lw $t1, gameScoreDigits
    print_int($t1)
    mul $t1, $t1, 2
    add $t1, $t1, -1
    li $t2, 64 
    sub $t1, $t2, $t1

    # Draw Score
    set_mem (gameScoreDigits, 0, 0)
    lw $t0, gameScores
    li $t2, 50
    jal DRAWSCORE

    jal BUFFTOSCREEN
    GAMEOVERLOOP:
        jal KEYBOARDINPUT
        sleep (100)
        j GAMEOVERLOOP

GAMELOOPSETUP:
    set_mem (characterX, 4, 0)
    set_mem (characterY, 28, 0)
    set_mem (enemyOneAttributes, 0, 0)
    set_mem (enemyOneAttributes, ENEMYONESPAWNDELAYMIN, 4)
    set_mem (characterHealth, 10, 0)
    set_mem (gameScores, 0, 0)
    set_mem (gameScoreDigits, 1, 0)

    GAMELOOPSTART:
        jal COLLISION
        jal ENEMYHANDLER

        # Draws background
        draw_sprite (backgroundImage, 128, 64, 0, 0)

        # Draws health
        jal DRAWHEALTH

        # Draws enemys
        jal DRAWENEMYONE

        # Draws character
        draw_sprite_memory (characterImage, characterW, characterH, characterX, characterY)

        # Draw Score
        set_mem (gameScoreDigits, 0, 0)
        lw $t0, gameScores
        li $t1, 1
        li $t2, 1
        jal DRAWSCORE

        # Death
        lw $t9, characterHealth
        beq $t9, $zero GAMEOVERSETUP

        jal BUFFTOSCREEN
        jal KEYBOARDINPUT

        lw $t9, gameScores
        add $t9, $t9, 1
        sw $t9, gameScores
        
        sleep (SLEEP_TIME)
        j GAMELOOPSTART

# functions

EXIT:
    li $v0, 10 # terminate the program gracefully
    syscall

BUFFTOSCREEN:
    lw $t0, displayBuffer
    lw $t1, displayWidth
    sll $t1, $t1, 2
    lw $t2, displayHeight

    mul $t3, $t1, $t2
    add $t3, $t3, $t0

    lw $t4, displayAddress

    BUFFTOSCREENLOOP:
        beq $t0, $t3, BUFFTOSCREENENDLOOP
        lw $t9, ($t0)
        sw $t9, ($t4)
        addi $t0, $t0, 4
        addi $t4, $t4, 4
        j BUFFTOSCREENLOOP
    BUFFTOSCREENENDLOOP:

    jr $ra

KEYBOARDINPUT:
    li $t9, 0xffff0000
    lw $t8, 0($t9)
    bne $t8, 1, KEYBOARDINPUTDONE
    lw $t2, 4($t9)

    # up
    bne $t2, 0x77, KEYBOARDINPUTW
        lw $t0, characterY
        beq	$t0, 0, KEYBOARDINPUTDONE
        addi $t0, $t0, -2
        sw $t0, characterY
    KEYBOARDINPUTW:

    # left
    bne $t2, 0x61, KEYBOARDINPUTA
        lw $t0, characterX
        beq	$t0, 0, KEYBOARDINPUTDONE
        addi $t0, $t0, -2
        sw $t0, characterX
    KEYBOARDINPUTA:
    
    # down
    bne $t2, 0x73, KEYBOARDINPUTS
        lw $t0, characterY
        lw $t1, characterH
        add $t1, $t1, $t0
        lw $t3, displayHeight
        beq	$t1, $t3, KEYBOARDINPUTDONE
        addi $t0, $t0, 2
        sw $t0, characterY
    KEYBOARDINPUTS:

    # right
    bne $t2, 0x64, KEYBOARDINPUTD
        lw $t0, characterX
        lw $t1, characterW
        add $t1, $t1, $t0
        lw $t3, displayWidth
        beq	$t1, $t3, KEYBOARDINPUTDONE
        addi $t0, $t0, 2
        sw $t0, characterX
    KEYBOARDINPUTD:

    # restarts / loads game
    bne $t2, 0x70, KEYBOARDINPUTP
        j GAMELOOPSETUP
    KEYBOARDINPUTP:
    
    # goes to game over
    bne $t2, 0x71, KEYBOARDINPUTQ
        j GAMEOVERSETUP
    KEYBOARDINPUTQ:
    
    # goes to main menu
    bne $t2, 0x6d, KEYBOARDINPUTM
        j MAINMENUSETUP
    KEYBOARDINPUTM:

    KEYBOARDINPUTDONE:
    jr $ra

DRAWSPRITE:
    # v0 = address of sprite
    # a0 = width of sprite
    # a1 = height of sprite
    # a2 = sprite x pos
    # a3 = sprite y pos

    move $t0, $v0   # t0 = address of sprite
    move $t1, $a0   # t1 = width of sprite
    move $t2, $a1   # t2 = height of sprite
    move $t3, $a2   # t3 = sprite x pos
    move $t4, $a3   # t4 = sprite y pos

    lw $t5, displayBuffer
    lw $t6, displayWidth
    mul $t7, $t4, $t6   # y * display width
    add $t7, $t7, $t3   # x + y * displaywidth
    sll $t7, $t7, 2     # (x + y * displaywidth) * 4
    add $t5, $t5, $t7

    sll $t6, $t6, 2

    li $t7, 0
    li $t8, 0

    DRAWSPRITELOOPY:
        beq $t8, $t2, DRAWSPRITELOOPYDONE
        DRAWSPRITELOOPX:
            beq $t7, $t1, DRAWSPRITELOOPXDONE
            
            lw $t9, ($t0)
            bltz $t9, DRAWSPRITEAFTERPIXELSTORE
            sw $t9, ($t5)
            DRAWSPRITEAFTERPIXELSTORE:

            addi $t0, $t0, 4
            addi $t5, $t5, 4
            addi $t7, $t7, 1
            j DRAWSPRITELOOPX
        DRAWSPRITELOOPXDONE:
        li $t7, 0
        move $t9, $t1
        sll $t9, $t9, 2
        sub $t5, $t5, $t9
        add $t5, $t5, $t6
        addi $t8, $t8, 1
        j DRAWSPRITELOOPY
    DRAWSPRITELOOPYDONE:

    jr $ra

DRAWHEALTH:
    draw_sprite(healthGrey, 29, 5, 98, 1)
    lw $t0, characterHealth
    mul $t0, $t0, 3
    bne $t0, 30, DRAWHEALTHFULLHEALTHCOMP
    add $t0, $t0, -1
    DRAWHEALTHFULLHEALTHCOMP:
    li $t1, 127
    sub $t1, $t1, $t0
    draw_sprite(healthRed, $t0, 5, $t1, 1)
    draw_sprite(healthMask, 29, 5, 98, 1)
    jr $ra

COLLISION: 
    lw $s0, enemyOneAttributes

    lw $t3, characterX
    lw $t4, characterY
    
    j ENEMYONECOLLISION
    COLLISIONONE:
        sll $t0, $s1, 3
        lw $t1, enemyOnePositions+0($t0)
        lw $t2, enemyOnePositions+4($t0)

        li $t9, 7
        add $t9, $t9, $t1
        bge $t3, $t9, COLLISIONCHECKDONE
        lw $t9, characterW
        add $t9, $t9, $t3
        ble $t9, $t1, COLLISIONCHECKDONE
        li $t9, 7
        add $t9, $t9, $t2
        bgt $t4, $t9, COLLISIONCHECKDONE
        lw $t9, characterH
        add $t9, $t9, $t4
        ble $t9, $t2, COLLISIONCHECKDONE

        # Collision
        lw $t9, characterHealth
        addi $t9, $t9, -1
        sw $t9, characterHealth

        # Set enemy pos to 1 so it gets removed by movement script
        li $t1, 1
        sw $t1, enemyOnePositions+0($t0)

        COLLISIONCHECKDONE:
        jr $ra

    ENEMYONECOLLISION:
        for ($s1, 0, $s0, COLLISIONONE)

    jr $ra

ENEMYHANDLER:
    save_ra
    jal ENEMYMOVEMENT
    load_ra

    lw $t2, enemyOneAttributes + 0($zero)
    lw $t3, enemyOneAttributes + 4($zero)
    bge $t2, ENEMYONEMAXAMOUNT, ENDENEMYHANDLERLOOP
    addi $t3, $t3, -1
    sw $t3, enemyOneAttributes + 4($zero)
    bge $t3, 0, ENDENEMYHANDLERLOOP
        rand_int_range($t5, ENEMYONESPAWNDELAYMIN, ENEMYONESPAWNDELAYMAX)
        set_mem (enemyOneAttributes, $t5, 4)
        add $t6, $t2, 1
        set_mem (enemyOneAttributes, $t6, 0) 

        sll $t2, $t2, 3
        rand_int_range($t4, 10, 40)
        set_mem (enemyOnePositions, 121, $t2)
        add $t2, $t2, 4
        set_mem (enemyOnePositions, $t4, $t2)

    ENDENEMYHANDLERLOOP:

    jr $ra

ENEMYMOVEMENT:
    lw $t7, enemyOneAttributes
    
    j ENEMYMOVEMENTFOR
    ENEMYMOVEMENTMOVE:
        sll $t4, $t2, 3
        lw $t9, enemyOnePositions+0($t4)
        addi $t9, $t9, -1
        sw $t9, enemyOnePositions+0($t4)
        bne $t9, $zero, ENEMYMOVEMENTREMOVEDONE
        li $t9, 120
        ENEMYMOVEMENTREMOVELOOP:
            beq $t4, $t9, ENEMYMOVEMENTREMOVELOOPDONE
            lw $t8, enemyOnePositions+8($t4)
            sw $t8, enemyOnePositions+0($t4)
            add $t4, $t4, 4
            j ENEMYMOVEMENTREMOVELOOP
        ENEMYMOVEMENTREMOVELOOPDONE:
            lw $t9, enemyOneAttributes
            addi $t9, $t9, -1
            sw $t9, enemyOneAttributes
        ENEMYMOVEMENTREMOVEDONE:
        jr $ra
    ENEMYMOVEMENTFOR:
        for ($t2, 0, $t7, ENEMYMOVEMENTMOVE)

    jr $ra

DRAWENEMYONE:
    lw $s0, enemyOneAttributes
    
    j ENEMYONEDRAWLOOP
    DRAWENEMYONELOOP:
        sll $t0, $s1, 3
        lw $t1, enemyOnePositions+0($t0)
        lw $t2, enemyOnePositions+4($t0)

        draw_sprite (enemyOneSprite, 7, 7, $t1, $t2)

        jr $ra
    ENEMYONEDRAWLOOP:
        for ($s1, 0, $s0, DRAWENEMYONELOOP)

    jr $ra

DRAWSCORE:
    # t0 score
    # t1 pos X
    # t2 pos Y
    li $t3, 10
    div $t0, $t3
    mfhi $t3 # remainder
    mflo $t4 # div
    beq $t4, 0, DRAWRECURSIONDONE
    push_stack ($t3)
    move $t0, $t4
    save_ra
    jal DRAWSCORE
    load_ra
    pop_stack ($t3)
    DRAWRECURSIONDONE:
    lw $t9, gameScoreDigits
    add $t9, $t9, 1
    sw $t9, gameScoreDigits

    push_stack($t2)
    push_stack($t1)

    bne $t3, 0, DRAWSCORE0
    draw_sprite (num0Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE0:

    bne $t3, 1, DRAWSCORE1
    draw_sprite (num1Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE1:
    
    bne $t3, 2, DRAWSCORE2
    draw_sprite (num2Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE2:
    
    bne $t3, 3, DRAWSCORE3
    draw_sprite (num3Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE3:
    
    bne $t3, 4, DRAWSCORE4
    draw_sprite (num4Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE4:
    
    bne $t3, 5, DRAWSCORE5
    draw_sprite (num5Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE5:
    
    bne $t3, 6, DRAWSCORE6
    draw_sprite (num6Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE6:
    
    bne $t3, 7, DRAWSCORE7
    draw_sprite (num7Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE7:
    
    bne $t3, 8, DRAWSCORE8
    draw_sprite (num8Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE8:
    
    bne $t3, 9, DRAWSCORE9
    draw_sprite (num9Img, 3, 5, $t1, $t2)
    j DRAWNUMDONE
    DRAWSCORE9:

    DRAWNUMDONE:

    pop_stack($t1)
    pop_stack($t2)
    add $t1, $t1, 4

    jr $ra